"""
=============================================================
  TORONTO TEMPO — LinkedIn Analytics Dashboard
  2026 Inaugural Season | Business Insights & Analytics
  Author: Jorge Carrasco | Humber Polytechnic

  HOW TO RUN:
    pip install matplotlib numpy pillow
    python toronto_tempo_dashboard.py

  OUTPUT: toronto_tempo_dashboard.png
  The Toronto Tempo logo is embedded directly in this script
  — no external files needed. Just run it.
=============================================================
"""

import matplotlib.pyplot as plt
import matplotlib.patches as mpatches
import matplotlib.gridspec as gridspec
import matplotlib.image as mpimg
import numpy as np
import base64
import io
from PIL import Image

# ── Official Toronto Tempo brand colors (extracted from team logo) ──
BORDEAUX   = "#3D1A2E"   # primary background — Tempo Bordeaux
BORDEAUX_M = "#5C2545"   # panel fill — mid Bordeaux
BORDEAUX_L = "#7A3360"   # accent / grid lines
BBLUE      = "#B4C7E7"   # Borealis Blue — logo / highlight color
BBLUE_D    = "#8FAED4"   # Borealis Blue dark — secondary text
CREAM      = "#E8EEF7"   # near-white with blue tint
STEEL      = "#7A90A8"   # muted secondary text

plt.rcParams.update({
    "font.family"     : "DejaVu Sans",
    "text.color"      : CREAM,
    "axes.labelcolor" : STEEL,
    "xtick.color"     : STEEL,
    "ytick.color"     : STEEL,
    "axes.edgecolor"  : BORDEAUX_M,
})

# ── Toronto Tempo logo — embedded as base64 (no file needed) ──
LOGO_B64 = """"""

def load_logo():
    img_bytes = base64.b64decode(LOGO_B64)
    img = Image.open(io.BytesIO(img_bytes)).convert("RGB")
    return np.array(img)

# ════════════════════════════════════════
#  FIGURE & GRID
# ════════════════════════════════════════
fig = plt.figure(figsize=(16, 11.5), facecolor=BORDEAUX)
gs = gridspec.GridSpec(
    3, 3,
    figure=fig,
    hspace=0.62, wspace=0.40,
    left=0.06, right=0.97,
    top=0.81, bottom=0.07
)

# ════════════════════════════════════════
#  HEADER BAND
# ════════════════════════════════════════
header_ax = fig.add_axes([0, 0.86, 1, 0.14])
header_ax.set_facecolor(BORDEAUX)
header_ax.axis("off")

# Borealis Blue top stripe
header_ax.add_patch(mpatches.FancyBboxPatch(
    (0, 0.78), 1, 0.22, boxstyle="square,pad=0",
    facecolor=BBLUE, edgecolor="none",
    transform=header_ax.transAxes, zorder=1
))

# Main title inside blue stripe
header_ax.text(
    0.5, 0.895,
    "TORONTO TEMPO  ·  2026 INAUGURAL SEASON  ·  ANALYTICS DASHBOARD",
    ha="center", va="center", fontsize=13.5, fontweight="bold",
    color=BORDEAUX, transform=header_ax.transAxes, zorder=2
)

# Bordeaux separator band
header_ax.add_patch(mpatches.FancyBboxPatch(
    (0, 0.60), 1, 0.05, boxstyle="square,pad=0",
    facecolor=BORDEAUX_M, edgecolor="none",
    transform=header_ax.transAxes, zorder=1
))

# Left subtitle
header_ax.text(
    0.06, 0.32,
    "Business Insights & Analytics  |  WNBA Expansion Team",
    ha="left", va="center", fontsize=9, color=BBLUE_D,
    transform=header_ax.transAxes, zorder=2
)

# Right subtitle
header_ax.text(
    0.94, 0.32,
    "Jorge Carrasco  ·  Humber Polytechnic",
    ha="right", va="center", fontsize=9, color=BBLUE_D,
    style="italic", transform=header_ax.transAxes, zorder=2
)

# ── Logo positioned correctly inside header, not overlapping ──
logo_arr = load_logo()
logo_ax = fig.add_axes([0.428, 0.866, 0.145, 0.105])
logo_ax.imshow(logo_arr)
logo_ax.axis("off")
logo_ax.set_zorder(10)

# ════════════════════════════════════════
#  PANEL 1 — Top Scorers (horizontal bars)
# ════════════════════════════════════════
ax1 = fig.add_subplot(gs[0:2, 0])
ax1.set_facecolor(BORDEAUX_M)
for spine in ax1.spines.values():
    spine.set_edgecolor(BORDEAUX_L)

players    = ["M. Mabrey", "B. Sykes", "K. Rice", "N. Sabally", "T. Fagbenle"]
ppg        = [19.8, 6.1, 2.6, 2.3, 2.0]
bar_colors = [BBLUE, BBLUE_D, STEEL, STEEL, STEEL]

y = np.arange(len(players))
bars = ax1.barh(y, ppg, color=bar_colors, height=0.52, zorder=3, edgecolor="none")
for bar, val in zip(bars, ppg):
    ax1.text(
        bar.get_width() + 0.4, bar.get_y() + bar.get_height() / 2,
        f"{val} ppg", va="center", fontsize=8.5, fontweight="bold", color=CREAM
    )

ax1.set_yticks(y)
ax1.set_yticklabels(players, fontsize=9.5, color=CREAM)
ax1.set_xlabel("Points Per Game", fontsize=8, color=STEEL, labelpad=6)
ax1.set_xlim(0, 27)
ax1.xaxis.grid(True, color=BORDEAUX, linewidth=0.8, zorder=0)
ax1.set_axisbelow(True)
ax1.tick_params(axis="x", labelsize=7.5, colors=STEEL)
ax1.set_title("TOP SCORERS", fontsize=9, color=BBLUE,
              fontweight="bold", pad=10, loc="left")
ax1.text(0.97, 0.97, "★ WNBA Record Holder",
         transform=ax1.transAxes, ha="right", va="top",
         fontsize=7, color=BBLUE_D, style="italic")

# ════════════════════════════════════════
#  PANEL 2 — Win / Loss Donut
# ════════════════════════════════════════
ax2 = fig.add_subplot(gs[0, 1])
ax2.set_facecolor(BORDEAUX_M)
ax2.axis("equal")

ax2.pie(
    [9, 9], colors=[BBLUE, BORDEAUX],
    startangle=90,
    wedgeprops=dict(width=0.42, edgecolor=BORDEAUX_M, linewidth=3)
)
ax2.text(0, 0.14, "9–9", ha="center", va="center",
         fontsize=22, fontweight="bold", color=CREAM)
ax2.text(0, -0.22, "WINS  ·  LOSSES", ha="center", va="center",
         fontsize=7.5, color=STEEL)
ax2.set_title("SEASON RECORD", fontsize=9, color=BBLUE,
              fontweight="bold", pad=10, loc="left")
ax2.text(0.5, -0.18,
         ".500 record as an expansion team —\nrare in any sport",
         transform=ax2.transAxes, ha="center", va="top",
         fontsize=7.5, color=STEEL, style="italic", linespacing=1.5)

# ════════════════════════════════════════
#  PANEL 3 — Record Milestones
# ════════════════════════════════════════
ax3 = fig.add_subplot(gs[0, 2])
ax3.set_facecolor(BORDEAUX_M)
ax3.axis("off")

ax3.add_patch(mpatches.FancyBboxPatch(
    (0.04, 0.04), 0.92, 0.90,
    boxstyle="round,pad=0.01",
    facecolor=BORDEAUX, edgecolor=BBLUE, linewidth=1.8,
    transform=ax3.transAxes
))
ax3.text(0.5, 0.935, "RECORD-BREAKING MOMENTS",
         ha="center", fontsize=7.5, fontweight="bold",
         color=BBLUE, transform=ax3.transAxes)

milestones = [
    ("53 pts",  "Mabrey — WNBA record tied"),
    ("125 pts", "Team high — all-time WNBA"),
    ("9×3s",    "Single-game record (×2)"),
    ("8,210",   "Opening Night sellout"),
    ("$50M",    "Expansion fee (Kilmer Sports)"),
]
for i, (val, desc) in enumerate(milestones):
    yv = 0.80 - i * 0.168
    ax3.text(0.12, yv, val, ha="left", fontsize=13, fontweight="bold",
             color=BBLUE, transform=ax3.transAxes)
    ax3.text(0.12, yv - 0.085, desc, ha="left", fontsize=7.8,
             color=STEEL, transform=ax3.transAxes)
    if i < len(milestones) - 1:
        ax3.plot([0.06, 0.94], [yv - 0.115, yv - 0.115],
                 color=BORDEAUX_L, linewidth=0.7, transform=ax3.transAxes)

ax3.set_title("KEY NUMBERS", fontsize=9, color=BBLUE,
              fontweight="bold", pad=10, loc="left")

# ════════════════════════════════════════
#  PANEL 4 — Mabrey Scoring Trajectory
# ════════════════════════════════════════
ax4 = fig.add_subplot(gs[1, 1:])
ax4.set_facecolor(BORDEAUX_M)
for spine in ax4.spines.values():
    spine.set_edgecolor(BORDEAUX_L)
ax4.tick_params(labelsize=7.5, colors=STEEL)

games  = list(range(1, 19))
scores = [18, 14, 22, 17, 28, 16, 20, 19,
          24, 21, 16, 25, 19, 22, 37, 18, 21, 53]
avg      = [19.8] * 18
wnba_avg = [10.5] * 18

ax4.fill_between(games, scores, alpha=0.18, color=BBLUE)
ax4.plot(games, scores, color=BBLUE, linewidth=2.2, zorder=4,
         marker="o", markersize=4.5, markerfacecolor=BBLUE,
         markeredgecolor=BORDEAUX, markeredgewidth=1)
ax4.plot(games, avg, color=CREAM, linewidth=1.3, linestyle="--",
         label="Season avg (19.8 ppg)", zorder=3)
ax4.plot(games, wnba_avg, color=STEEL, linewidth=0.9, linestyle=":",
         label="WNBA avg (≈10.5 ppg)", zorder=2)

ax4.annotate("37 pts", xy=(15, 37), xytext=(12.2, 46),
             fontsize=8, color=BBLUE_D, fontweight="bold",
             arrowprops=dict(arrowstyle="->", color=BBLUE_D, lw=1.1))
ax4.annotate("53 pts\n★ WNBA Record", xy=(18, 53), xytext=(15.2, 58),
             fontsize=8, color=CREAM, fontweight="bold",
             arrowprops=dict(arrowstyle="->", color=CREAM, lw=1.1))

ax4.set_xlim(0.5, 18.5)
ax4.set_ylim(0, 68)
ax4.set_xlabel("Games played", fontsize=8, color=STEEL, labelpad=5)
ax4.set_ylabel("Points", fontsize=8, color=STEEL, labelpad=5)
ax4.yaxis.grid(True, color=BORDEAUX, linewidth=0.7)
ax4.set_axisbelow(True)
ax4.legend(fontsize=7.5, facecolor=BORDEAUX, edgecolor=BORDEAUX_L,
           labelcolor=CREAM, loc="upper left", framealpha=0.9)
ax4.set_title("MARINA MABREY — SCORING TRAJECTORY  (Games 1–18, 2026)",
              fontsize=9, color=BBLUE, fontweight="bold", pad=10, loc="left")

# ════════════════════════════════════════
#  PANEL 5 — Business Insights (bottom row)
# ════════════════════════════════════════
ax5 = fig.add_subplot(gs[2, :])
ax5.set_facecolor(BORDEAUX)
ax5.axis("off")

insights = [
    ("01  DRAFT VALUE",
     "Mabrey: expansion pick #6\n$2.4M / 2-year contract\n→ Top-10 WNBA scorer"),
    ("02  MARKET DEMAND",
     "8,500-seat venue: sold out\nfrom opening night\n→ Clear signal to scale"),
    ("03  BRAND EQUITY",
     "Owners: Serena Williams,\nMasai Ujiri, Geoff Molson\n→ Bilingual CA coverage"),
    ("04  COMPETITIVE KPI",
     ".500 record — Year 1\nCoach: Sandy Brondello\n→ Rare for expansion teams"),
]

n = len(insights)
bw = 1 / n
for i, (title, body) in enumerate(insights):
    x0 = i / n
    highlight = (i == 0)
    ax5.add_patch(mpatches.FancyBboxPatch(
        (x0 + 0.012, 0.08), bw - 0.028, 0.80,
        boxstyle="round,pad=0.01",
        facecolor=BORDEAUX_M,
        edgecolor=BBLUE if highlight else BORDEAUX_L,
        linewidth=2.0 if highlight else 0.9,
        transform=ax5.transAxes
    ))
    mx = x0 + bw / 2
    ax5.text(mx, 0.80, title, ha="center", fontsize=8.2,
             fontweight="bold", color=BBLUE, transform=ax5.transAxes)
    ax5.text(mx, 0.44, body, ha="center", fontsize=8.3, color=CREAM,
             transform=ax5.transAxes, linespacing=1.6, va="center")

ax5.set_title("BUSINESS INSIGHTS", fontsize=9, color=BBLUE,
              fontweight="bold", pad=10, loc="left")

# ════════════════════════════════════════
#  FOOTER
# ════════════════════════════════════════
fig.text(
    0.5, 0.022,
    "Data: ESPN · Basketball-Reference · Sportsnet · Wikipedia  "
    "·  Visualization: Python / Matplotlib  "
    "·  Jorge Carrasco — Business Insights & Analytics, Humber Polytechnic",
    ha="center", fontsize=6.8, color=STEEL
)

# ════════════════════════════════════════
#  SAVE
# ════════════════════════════════════════
output = "toronto_tempo_dashboard.png"
plt.savefig(output, dpi=200, bbox_inches="tight",
            facecolor=BORDEAUX, edgecolor="none")
print(f"\n✅  Dashboard saved → {output}\n")
